# merge appended data rows into the header table (hdr() closes its table)
for _q in Q:
    if '</tr></table><tr>' in _q['stem']:
        _q['stem'] = _q['stem'].replace('</tr></table><tr>', '</tr><tr>', 1).replace('</tr>{FIG}', '</tr></table>{FIG}', 1)
